"""只驗封存後正式cohort的一致來源、實際種子、工具雜湊及原生save，不推勝率。"""
import pathlib,json,sys,hashlib,subprocess
lab=pathlib.Path(sys.argv[1]);freeze=json.loads(pathlib.Path(sys.argv[2]).read_text());out=pathlib.Path(sys.argv[3]);out.parent.mkdir(parents=True,exist_ok=True)
expected=freeze['commonToolHashes'];results={};hashfile=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for role in 'ABC':
 pub=lab/'players'/role;private=lab/'private-observer'/role/'after';session=json.loads((pub/'after/session.json').read_text());r=json.loads((private/'result.json').read_text());samples=[json.loads(x) for x in (private/'samples.jsonl').read_text().splitlines()];h=session['harness'];seeds=sorted({x.get('seed') for x in samples if not x.get('inMenu') and x.get('seed') is not None});saves=[]
 for p in sorted(private.glob('native-save-*.json')):
  x=json.loads(p.read_text());saves.append({'file':p.name,'sha256':hashfile(p),'nameMatchesSHA':p.stem=='native-save-'+hashfile(p),'seed':x.get('seed'),'civ':x.get('civId'),'biome':x.get('biomeId'),'difficulty':x.get('difficulty'),'phase':x.get('phase')})
 seal='PUBLIC-SHA256SUMS' if (pub/'PUBLIC-SHA256SUMS').exists() else 'SHA256SUMS'
 checked=subprocess.run(['sha256sum','-c',seal],cwd=pub,text=True,capture_output=True)
 checks={'source':session['source']==freeze['gameBuildSource']==r['source'],'resources':session['verified']['hash']=='SHA256_MATCH_167_FILES','domSeed':session['seed']=='FUN-LAB-BASE-281','actualSeeds':seeds==[1116648138],'gatewayHash':h['gatewaySHA256']==expected['tools/qa/fun-lab-v2-8e41d6b2/player-gateway.mjs'],'observerHash':h['observerSHA256']==expected['tools/qa/fun-lab-v2-8e41d6b2/observer.mjs'],'instructionsHash':h['instructionsSHA256']==expected['docs/feedback/fun-lab-v2-8e41d6b2/FORMAL-PLAYER-INSTRUCTIONS.md'],'same1200WallCap':session['limits']['wallLimitMs']==1200000,'noResume':not session.get('resume'),'nativeSave':bool(saves) and all(x['nameMatchesSHA'] and x['seed']==1116648138 and x['civ']=='FRK' and x['biome']=='steppe' and x['difficulty']=='normal' for x in saves),'publicSeal':checked.returncode==0}
 results[role]={'checks':checks,'allPass':all(checks.values()),'phase':r['state']['phase'],'wave':r['state']['wave'],'stopReason':r['stopReason'],'cap':r['cap'],'pageErrors':r['errors'],'nativeSaves':saves,'sealLines':len(checked.stdout.splitlines()),'sealFailure':checked.stderr if checked.returncode else None}
result={'scope':'同一freeze的三個代理角色；不是人類統計或勝率因果研究','players':results,'status':'PASS' if all(x['allPass'] for x in results.values()) else 'FAIL'};out.write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n');print(json.dumps({'status':result['status'],'players':{k:v['checks'] for k,v in results.items()}},ensure_ascii=False));sys.exit(0 if result['status']=='PASS' else 1)
